1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	export type Damage = { itemType: string; amount: number };
8	export type Incident = { cause: string; damages: Damage[] };
9	
10	export type Step = {
11	  op: string;
12	  items?: Item[];
13	  policy?: number;
14	  incident?: Incident;
15	};
16	export type Customer = { yearsWithMHPCO: number };
17	export type Scenario = { customer: Customer; steps: Step[] };
18	
19	export type QuoteResult = { premium: number };
20	export type ClaimResult = { payout: number; remainingCap: number };
21	export type StepResult = QuoteResult | ClaimResult;
22	export type ScenarioResult = { results: StepResult[] };
23	
24	const BASE_PREMIUMS: Record<string, number> = {
25	  sword: 100,
26	  amulet: 60,
27	  staff: 80,
28	  potion: 40,
29	  rune: 25,
30	  moonstone: 25,
31	};
32	
33	const INSURANCE_VALUES: Record<string, number> = {
34	  sword: 1000,
35	  amulet: 600,
36	  staff: 800,
37	  potion: 400,
38	  rune: 250,
39	  moonstone: 250,
40	};
41	
42	const DEDUCTIBLE_PER_DAMAGE = 100;
43	const CAP_MULTIPLIER = 2;
44	
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	const PROCESSING_FEE = 5;
47	
48	const CURSE_SURCHARGE_RATE = 0.5;
49	const HIGH_ENCHANTMENT_THRESHOLD = 5;
50	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
51	const LOYALTY_THRESHOLD_YEARS = 2;
52	const LOYALTY_DISCOUNT_RATE = 0.2;
53	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
54	
55	const BLOCK_SIZE = 3;
56	const BLOCK_BASE_PREMIUM = 60;
57	
58	const countByType = (items: Item[]): Map<string, number> => {
59	  const counts = new Map<string, number>();
60	  for (const item of items) {
61	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
62	  }
63	  return counts;
64	};
65	
66	const basePremiumForType = (type: string, count: number): number =>
67	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
68	
69	const policyBasePremium = (items: Item[]): number =>
70	  [...countByType(items)]
71	    .map(([type, count]) => basePremiumForType(type, count))
72	    .reduce((total, premium) => total + premium, 0);
73	
74	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
75	
76	const isCursed = (item: Item): boolean => item.cursed === true;
77	
78	const isHighlyEnchanted = (item: Item): boolean =>
79	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
80	
81	const curseSurcharge = (item: Item): number =>
82	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
83	
84	const highEnchantmentSurcharge = (item: Item): number =>
85	  isHighlyEnchanted(item)
86	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
87	    : 0;
88	
89	const itemModifierSurcharges = (items: Item[]): number =>
90	  items
91	    .map((item) => curseSurcharge(item) + highEnchantmentSurcharge(item))
92	    .reduce((total, surcharge) => total + surcharge, 0);
93	
94	const isLoyalCustomer = (customer: Customer): boolean =>
95	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
96	
97	// Policy-wide modifiers are rates applied to the policy base premium.
98	// Surcharges are positive, discounts negative; they sum to one net rate.
99	const policyModifierRates = (
100	  customer: Customer,
101	  isFollowUpContract: boolean,
102	): number[] => [
103	  FIRST_INSURANCE_SURCHARGE_RATE,
104	  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT_RATE : 0,
105	  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0,
106	];
107	
108	const netPolicyModifierRate = (
109	  customer: Customer,
110	  isFollowUpContract: boolean,
111	): number =>
112	  policyModifierRates(customer, isFollowUpContract).reduce(
113	    (total, rate) => total + rate,
114	    0,
115	  );
116	
117	const quotePremium = (
118	  customer: Customer,
119	  items: Item[] = [],
120	  isFollowUpContract = false,
121	): number => {
122	  const policyBase = policyBasePremium(items);
123	  const policyModifiers =
124	    policyBase * netPolicyModifierRate(customer, isFollowUpContract);
125	  return Math.ceil(
126	    policyBase +
127	      itemModifierSurcharges(items) +
128	      policyModifiers +
129	      PROCESSING_FEE,
130	  );
131	};
132	
133	type Policy = { items: Item[]; remainingCap: number };
134	
135	const insuranceSum = (items: Item[]): number =>
136	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
137	
138	const damagePayout = (damage: Damage): number =>
139	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
140	
141	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
142	  const payout = Math.floor(
143	    incident.damages.reduce((total, damage) => total + damagePayout(damage), 0),
144	  );
145	  policy.remainingCap -= payout;
146	  return { payout, remainingCap: policy.remainingCap };
147	};
148	
149	export const runScenario = (scenario: Scenario): ScenarioResult => {
150	  const policies = new Map<number, Policy>();
151	  let quotesSoFar = 0;
152	
153	  const results = scenario.steps.map((step, index): StepResult => {
154	    if (step.op === "claim") {
155	      const policy = policies.get(step.policy ?? -1)!;
156	      return settleClaim(policy, step.incident!);
157	    }
158	
159	    const items = step.items ?? [];
160	    const isFollowUpContract = quotesSoFar > 0;
161	    quotesSoFar += 1;
162	    policies.set(index, {
163	      items,
164	      remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
165	    });
166	    return {
167	      premium: quotePremium(scenario.customer, items, isFollowUpContract),
168	    };
169	  });
170	
171	  return { results };
172	};
